/*
Unreal engine HLSL custom node. Return a float3 with planar Uvs (x,y) and horizontal height (z).

Input :
    - Height (constant node, arbitrary)
    - Tiling (constant node, arbitrary)
    - CameraPosition (CameraPositionWS node)
    - CameraVector (CameraVectorWS node)

Output :
    - Mask (float)

HLSL :
    // Calculate plane uvs
    float plane = (Height - CameraPosition.z) / CameraVector.z;
    return float3((CameraPosition.xy + CameraVector.xy * plane) / Tiling, max(CameraVector.z * -1.0, 0.0));
*/

const float cloudsAltitude = 1.0;
const float fieldOfView = 60.0;

mat3 GetRotationMatrix(vec3 unitAxis, float angle) {
	float cosine = cos(angle);

	vec3 axis = unitAxis * sin(angle);
	vec3 tmp = unitAxis - unitAxis * cosine;

	return mat3(
		unitAxis.x * tmp.x + cosine, unitAxis.x * tmp.y - axis.z, unitAxis.x * tmp.z + axis.y,
		unitAxis.y * tmp.x + axis.z, unitAxis.y * tmp.y + cosine, unitAxis.y * tmp.z - axis.x,
		unitAxis.z * tmp.x - axis.y, unitAxis.z * tmp.y + axis.x, unitAxis.z * tmp.z + cosine
	);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Camera position
    vec3 viewPosition = vec3(0.0,0.0,0.0);

    // Calculate view direction
    vec3 viewDirection;
    float zrot =  radians(360.0) * iMouse.x / iResolution.x;
    float xrot = -radians(90.0) * ((iMouse.x + iMouse.y) < 1.5 ? 0.2 : (iMouse.y / iResolution.y)) - radians(90.0);
    mat3 viewRot = GetRotationMatrix(vec3(0.0, 0.0, 1.0), zrot)
                 * GetRotationMatrix(vec3(1.0, 0.0, 0.0), xrot);
    viewDirection.xy = (2.0 * fragCoord - iResolution.xy) * tan(radians(fieldOfView) / 2.0) / iResolution.y;
    viewDirection.z = -1.0;
    viewDirection = viewRot * normalize(viewDirection);

    // Create plane uvs
    float tPlane = (cloudsAltitude - viewPosition.z) / viewDirection.z;
    vec2 cloudPosition = viewPosition.xy + viewDirection.xy * tPlane;

    // Debug view
    vec3 uvs = vec3(fract(cloudPosition*1.0), max(viewDirection.z, 0.0));

    uvs *= uvs.z;

    fragColor = vec4(uvs,1.0);
}
